The Python script converts a CSV file with `item` and `quantity` headers into a JSON array of objects. It normalizes item names by collapsing all whitespace to single spaces and casefolding, skipping empty names, and summing quantities for duplicate normalized items. Blank quantities are treated as 1. The output is sorted by normalized item name.

```python
import csv
import json
import sys

def main():
    if len(sys.argv) < 2:
        return

    filename = sys.argv[1]
    data = {}

    try:
        with open(filename, mode='r', encoding='utf-8', newline='') as f:
            reader = csv.DictReader(f)
            for row in reader:
                raw_item = row.get('item', '')
                raw_qty = row.get('quantity', '')

                # Normalize item name: collapse whitespace and casefold
                normalized_item = " ".join(raw_item.split()).casefold()

                if not normalized_item:
                    continue

                # Parse quantity: blank is 1, else base-10 integer
                if not raw_qty.strip():
                    qty = 1
                else:
                    try:
                        qty = int(raw_qty.strip())
                    except ValueError:
                        continue

                data[normalized_item] = data.get(normalized_item, 0) + qty
    except FileNotFoundError:
        return

    # Sort by normalized name and prepare output
    sorted_items = sorted(data.items())
    output = [{"item": k, "quantity": v} for k, v in sorted_items]

    print(json.dumps(output))

if __name__ == "__main__":
    main()
```

